before.source:
@startuml
layout horizontal
@layout
node DocumentBefore 0 160
node Preview 255 0
node CharacterCount 255 160
node SaveButton 255 320
@endlayout
class DocumentBefore {
  + text
  + setText(text)
}
class Preview {
  + text
}
class CharacterCount {
  + text
}
class SaveButton {
  + enabled
}
DocumentBefore --> "0..1" Preview : preview
DocumentBefore --> "0..1" CharacterCount : count
DocumentBefore --> "0..1" SaveButton : save
@enduml

roles.source:
@startuml
layout square
class Subject {
  - observers: Observer collection
  + attach(observer)
  + detach(observer)
  # notifyObservers(text)
}
interface Observer {
  + update(text)
}
class ConcreteSubject {
  - state: text
  + setText(text)
}
class ConcreteObserver {
  - viewState
  + update(text)
}
ConcreteSubject --|> Subject
ConcreteObserver ..|> Observer
Subject --> "0..*" Observer : notifies
@enduml

